/*updateMasterMpSoOrderStandbyOrderReqDetailPop_1*/
  UPDATE ICOMPRDT
        SET TARGET_PRICE = #{UNIT_PRICE}
           , LIST_PRICE = #{LIST_PRICE}
           , AGENT = #{AGENT}
       WHERE BUYER = #{st_buyer}
         AND PR_NO = #{PR_NO}
         AND PR_SEQ = #{PR_SEQ}


	/*updateMasterMpSoOrderStandbyOrderReqDetailPop_2*/
		UPDATE IF_PROGRESS
               SET IF_FLAG ='C'
				,CHANGE_DATE =TO_CHAR(SYSDATE,'YYYYMMDD')
				,CHANGE_TIME = TO_CHAR(SYSDATE,'HHMISS')
				,AGENCY_USER_ID =  #{USER_ID}
				,CONFIRM_DATE =TO_CHAR(SYSDATE,'YYYYMMDD')
				,CONFIRM_TIME = TO_CHAR(SYSDATE,'HHMISS')
	       WHERE BUYER     = #{st_buyer}
	         AND GUBUN     = 'XX'
	         AND LEGACY_NO = #{REF_NO}
	         AND REVISION  = (SELECT /*+ INDEX_DESC(A SYS_C0041013) */ REVISION
	                           FROM IF_PROGRESS A
	                          WHERE BUYER =  #{st_buyer}
	                            AND GUBUN = 'XX'
	                            AND LEGACY_NO = #{REF_NO}
	                            AND ROWNUM = 1
	                           )
